head.b:skin:
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body {
width: 100%;
min-height: 100vh;
background-color: #f3e9dc;
color: #221104;
font-family: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
line-height: 1.6;
-webkit-font-smoothing: antialiased;
}
img { max-width: 100%; height: auto; display: block; }
a { text-decoration: none; color: inherit; transition: all 0.2s ease; }
#qia-portal-root { display: none; }
/* GOOGLE MATERIAL SYMBOLS */
.ms {
font-family: 'Material Symbols Rounded';
font-weight: normal; font-style: normal; font-size: 24px; line-height: 1;
letter-spacing: normal; text-transform: none; display: inline-block;
white-space: nowrap; word-wrap: normal; direction: ltr;
-webkit-font-feature-settings: 'liga'; font-feature-settings: 'liga';
font-variation-settings: 'FILL' 1, 'wght' 500, 'GRAD' 0, 'opsz' 24;
-webkit-font-smoothing: antialiased;
}
.wa-ic { width: 20px; height: 20px; fill: currentColor; flex-shrink: 0; }
.qia-btn .ms { font-size: 20px; }
.qia-badge .ms { font-size: 16px; }
.qia-card-icon .ms { font-size: 28px; }
.qia-mobile-toggle .ms { font-size: 26px; }
.qia-landing {
--bg: #f3e9dc;
--ink: #221104;
--ink-soft: #4F280C;
--gold: #F0AF43;
--gold-soft: #D4934E;
--brown: #81511D;
--brown-deep: #4F280C;
--cream: #f3e9dc;
--border-soft: rgba(129, 81, 29, 0.25);
--border-gold: rgba(240, 175, 67, 0.45);
background: #f3e9dc;
color: #221104;
min-height: 100vh;
position: relative;
overflow-x: hidden;
}
.qia-container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.qia-navbar {
position: sticky; top: 0; z-index: 1000;
background: rgba(243, 233, 220, 0.9);
backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px);
border-bottom: 1px solid rgba(129, 81, 29, 0.2);
}
.qia-navbar-inner { display: flex; align-items: center; justify-content: space-between; height: 80px; }
.qia-brand { display: flex; align-items: center; gap: 12px; font-weight: 800; font-size: 22px; color: #221104; }
.qia-brand-logo {
height: 44px; width: auto; max-height: 44px; object-fit: contain; display: block;
}
.qia-brand-text span { color: #81511D; }
.qia-nav-links { display: flex; align-items: center; gap: 32px; }
.qia-nav-links a { font-weight: 600; font-size: 15px; color: #4F280C; }
.qia-nav-links a:hover { color: #81511D; }
.qia-nav-actions { display: flex; align-items: center; gap: 14px; }
.qia-btn {
display: inline-flex; align-items: center; justify-content: center; gap: 8px;
padding: 12px 26px; border-radius: 99px; font-weight: 700; font-size: 14px;
cursor: pointer; border: 1px solid transparent;
transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
.qia-btn-primary {
background: linear-gradient(135deg, #F0AF43, #D4934E);
color: #221104; box-shadow: 0 4px 20px rgba(240, 175, 67, 0.35);
}
.qia-btn-primary:hover { transform: translateY(-2px); box-shadow: 0 8px 25px rgba(240, 175, 67, 0.5); }
.qia-btn-wa {
background: linear-gradient(135deg, #4F280C, #221104);
color: #f3e9dc; box-shadow: 0 4px 20px rgba(34, 17, 4, 0.25);
}
.qia-btn-wa:hover { transform: translateY(-2px); box-shadow: 0 8px 25px rgba(34, 17, 4, 0.4); }
.qia-btn-outline { border-color: rgba(129, 81, 29, 0.4); background: rgba(212, 147, 78, 0.12); color: #4F280C; }
.qia-btn-outline:hover { border-color: #81511D; color: #81511D; background: rgba(212, 147, 78, 0.2); transform: translateY(-2px); }
.qia-btn-lg { padding: 16px 36px; font-size: 16px; }
.qia-mobile-toggle { display: none; background: transparent; border: none; color: #221104; cursor: pointer; padding: 8px; }
.qia-hero { padding: 100px 0 80px; text-align: center; position: relative; }
.qia-hero::before {
content: ''; position: absolute; top: -100px; left: 50%; transform: translateX(-50%);
width: 600px; height: 600px;
background: radial-gradient(circle, rgba(240, 175, 67, 0.2) 0%, rgba(243, 233, 220, 0) 70%);
pointer-events: none;
}
.qia-badge {
display: inline-flex; align-items: center; gap: 8px; padding: 8px 20px; border-radius: 99px;
background: rgba(240, 175, 67, 0.15); border: 1px solid rgba(129, 81, 29, 0.3);
color: #81511D; font-size: 13px; font-weight: 700; letter-spacing: 0.5px; margin-bottom: 24px;
}
.qia-hero h1 { font-size: 52px; font-weight: 800; line-height: 1.2; color: #221104; max-width: 900px; margin: 0 auto 24px; }
.qia-hero h1 span { background: linear-gradient(135deg, #D4934E, #81511D); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }
.qia-hero p { font-size: 19px; color: #4F280C; max-width: 680px; margin: 0 auto 40px; line-height: 1.7; }
.qia-hero-ctas { display: flex; align-items: center; justify-content: center; gap: 16px; flex-wrap: wrap; margin-bottom: 60px; }
.qia-stats {
display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px;
background: #221104; border: 1px solid rgba(240, 175, 67, 0.25);
border-radius: 24px; padding: 32px; max-width: 1000px; margin: 0 auto;
}
.qia-stat-item { text-align: center; }
.qia-stat-num { font-size: 32px; font-weight: 800; color: #F0AF43; margin-bottom: 4px; }
.qia-stat-label { font-size: 13px; color: rgba(243, 233, 220, 0.75); font-weight: 600; }
.qia-section { padding: 100px 0; }
.qia-section-header { text-align: center; max-width: 680px; margin: 0 auto 60px; }
.qia-section-eyebrow { color: #81511D; font-size: 13px; font-weight: 800; text-transform: uppercase; letter-spacing: 1.5px; margin-bottom: 12px; display: block; }
.qia-section-title { font-size: 38px; font-weight: 800; color: #221104; margin-bottom: 16px; }
.qia-section-desc { font-size: 16px; color: #4F280C; }
.qia-grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 28px; }
.qia-card {
background: #221104; border: 1px solid rgba(240, 175, 67, 0.2);
border-radius: 20px; padding: 36px 28px; transition: all 0.3s ease; position: relative;
}
.qia-card:hover { background: #4F280C; border-color: rgba(240, 175, 67, 0.5); transform: translateY(-6px); box-shadow: 0 12px 30px rgba(34, 17, 4, 0.25); }
.qia-card-icon {
width: 56px; height: 56px; border-radius: 16px; background: rgba(240, 175, 67, 0.12);
border: 1px solid rgba(240, 175, 67, 0.3); display: flex; align-items: center; justify-content: center;
color: #F0AF43; margin-bottom: 24px;
}
.qia-card h3 { font-size: 20px; font-weight: 700; color: #f3e9dc; margin-bottom: 12px; }
.qia-card p { font-size: 14.5px; color: rgba(243, 233, 220, 0.7); line-height: 1.6; }
.qia-grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 28px; }
.qia-program-card {
background: #4F280C; border: 1px solid rgba(240, 175, 67, 0.25);
border-radius: 24px; padding: 36px 28px; transition: all 0.3s ease;
display: flex; flex-direction: column; justify-content: space-between;
}
.qia-program-card:hover { border-color: rgba(240, 175, 67, 0.55); transform: translateY(-4px); }
.qia-tag {
display: inline-block; padding: 6px 16px; border-radius: 99px;
background: rgba(240, 175, 67, 0.15); border: 1px solid rgba(240, 175, 67, 0.4);
color: #F0AF43; font-size: 12px; font-weight: 700; margin-bottom: 20px;
}
.qia-program-card h3 { font-size: 24px; font-weight: 800; color: #f3e9dc; margin-bottom: 12px; }
.qia-program-card p { font-size: 15px; color: rgba(243, 233, 220, 0.75); margin-bottom: 24px; }
.qia-program-list { list-style: none; display: flex; flex-direction: column; gap: 12px; margin-bottom: 32px; }
.qia-program-list li { display: flex; align-items: center; gap: 10px; font-size: 14.5px; color: #f3e9dc; }
.qia-program-list li::before {
content: 'check';
font-family: 'Material Symbols Rounded';
font-size: 14px; font-weight: normal; font-style: normal; line-height: 1;
display: inline-flex; align-items: center; justify-content: center;
width: 20px; height: 20px; border-radius: 50%; background: rgba(240, 175, 67, 0.2);
color: #F0AF43; flex-shrink: 0;
-webkit-font-feature-settings: 'liga'; font-feature-settings: 'liga';
font-variation-settings: 'FILL' 1, 'wght' 600, 'GRAD' 0, 'opsz' 20;
}
.qia-portal-badge { display: inline-block; font-size: 11px; font-weight: 800; text-transform: uppercase; letter-spacing: 1px; color: #F0AF43; margin-bottom: 8px; }
.qia-faq-list { max-width: 800px; margin: 0 auto; display: flex; flex-direction: column; gap: 16px; }
.qia-faq-item { background: #221104; border: 1px solid rgba(240, 175, 67, 0.2); border-radius: 16px; overflow: hidden; transition: all 0.2s ease; }
.qia-faq-btn {
width: 100%; padding: 22px 28px; display: flex; align-items: center; justify-content: space-between;
background: transparent; border: none; color: #f3e9dc; font-weight: 700; font-size: 16px; text-align: left; cursor: pointer;
}
.qia-faq-icon { color: #F0AF43; transition: transform 0.3s ease; }
.qia-faq-icon .ms { font-size: 22px; }
.qia-faq-body { max-height: 0; overflow: hidden; padding: 0 28px; color: rgba(243, 233, 220, 0.7); font-size: 15px; line-height: 1.7; transition: all 0.3s ease; }
.qia-faq-item.is-active { border-color: rgba(240, 175, 67, 0.5); }
.qia-faq-item.is-active .qia-faq-icon { transform: rotate(45deg); }
.qia-faq-item.is-active .qia-faq-body { max-height: 200px; padding-bottom: 22px; }
.qia-cta-box {
background: linear-gradient(135deg, rgba(240, 175, 67, 0.25), rgba(212, 147, 78, 0.3));
border: 1px solid rgba(129, 81, 29, 0.35); border-radius: 32px; padding: 60px 40px;
text-align: center; position: relative; overflow: hidden;
}
.qia-cta-box h2 { font-size: 36px; font-weight: 800; color: #221104; margin-bottom: 16px; }
.qia-cta-box p { font-size: 17px; color: #4F280C; max-width: 600px; margin: 0 auto 36px; }
.qia-footer { border-top: 1px solid rgba(240, 175, 67, 0.25); padding: 40px 0; background: #221104; }
.qia-footer-inner { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 20px; }
.qia-footer p { font-size: 14px; color: rgba(243, 233, 220, 0.7); }
.qia-footer-links { display: flex; gap: 24px; }
.qia-footer-links a { font-size: 14px; color: rgba(243, 233, 220, 0.8); font-weight: 600; }
.qia-footer-links a:hover { color: #F0AF43; }
.qia-article { background: rgba(212, 147, 78, 0.12); border: 1px solid rgba(129, 81, 29, 0.25); padding: 48px 40px; margin-top: 20px; }
.qia-article:hover { transform: none; box-shadow: none; background: rgba(212, 147, 78, 0.12); }
.qia-article-title { font-size: 34px; font-weight: 800; color: #221104; margin-bottom: 24px; line-height: 1.3; }
.qia-post-body { color: #221104; font-size: 16.5px; line-height: 1.85; }
.qia-post-body p { margin: 0 0 18px; }
.qia-post-body h2, .qia-post-body h3, .qia-post-body h4 { color: #81511D; margin: 28px 0 14px; }
.qia-post-body img { border-radius: 16px; margin: 24px 0; }
.qia-post-body a { color: #81511D; text-decoration: underline; }
.qia-post-body blockquote { border-left: 4px solid #F0AF43; padding-left: 20px; color: #4F280C; font-style: italic; margin: 20px 0; }
.qia-list-card { background: rgba(212, 147, 78, 0.12); border: 1px solid rgba(129, 81, 29, 0.25); }
.qia-list-card:hover { background: rgba(212, 147, 78, 0.2); border-color: rgba(240, 175, 67, 0.5); }
.qia-list-card h3 a { color: #221104; }
.qia-list-card h3 a:hover { color: #81511D; }
.qia-list-card p { color: #4F280C; }
@media (max-width: 992px) {
.qia-hero h1 { font-size: 40px; }
.qia-grid-3 { grid-template-columns: repeat(2, 1fr); }
.qia-stats { grid-template-columns: repeat(2, 1fr); gap: 24px; }
}
@media (max-width: 768px) {
.qia-mobile-toggle { display: block; }
.qia-nav-links {
position: absolute; top: 80px; left: 0; right: 0; background: #f3e9dc;
border-bottom: 1px solid rgba(129, 81, 29, 0.25); flex-direction: column;
padding: 24px; gap: 20px; display: none;
}
.qia-nav-links.is-open { display: flex; }
.qia-nav-actions { display: none; }
.qia-grid-3, .qia-grid-2 { grid-template-columns: 1fr; }
.qia-hero h1 { font-size: 32px; }
.qia-hero p { font-size: 16px; }
.qia-stats { grid-template-columns: 1fr; }
.qia-footer-inner { flex-direction: column; text-align: center; }
.qia-article { padding: 28px 20px; }
.qia-article-title { font-size: 26px; }
}

body.script:
//
(function() {
var mobileToggle = document.getElementById('qiaMobileToggle');
var navLinks     = document.getElementById('qiaNavLinks');
if (mobileToggle && navLinks) {
mobileToggle.addEventListener('click', function() {
navLinks.classList.toggle('is-open');
});
}
var faqBtns = document.querySelectorAll('.qia-faq-btn');
faqBtns.forEach(function(btn) {
btn.addEventListener('click', function() {
var item = this.parentElement;
var isActive = item.classList.contains('is-active');
document.querySelectorAll('.qia-faq-item').forEach(function(el) {
el.classList.remove('is-active');
});
if (!isActive) {
item.classList.add('is-active');
}
});
});
var path = window.location.pathname.toLowerCase();
if (path.indexOf('/p/') !== -1) {
var landing = document.querySelector('.qia-landing');
if (landing) { landing.style.display = 'none'; }
var root = document.getElementById('qia-portal-root');
if (root) {
root.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;z-index:99999;background:#221104;display:block;';
var GAS_BASE = 'https://script.google.com/macros/s/AKfycbxdMQpEUGCxa3W9BB_HM5zIU71Q8b0OZFepAgOY0thu2hRzxC2HbNfEPFvzpoqNQoTc/exec?authuser=0';
var iframeSrc = GAS_BASE;
if (path.indexOf('/p/admin') !== -1) {
iframeSrc = GAS_BASE + '&p=admin';
} else if (path.indexOf('/p/mentor') !== -1) {
iframeSrc = GAS_BASE + '&p=mentor';
}
var frame = document.createElement('iframe');
frame.src = iframeSrc;
frame.style.cssText = 'width:100%;height:100%;border:none;display:block;';
frame.setAttribute('allowfullscreen', 'true');
frame.setAttribute('scrolling', 'yes');
frame.setAttribute('title', 'Portal QIA');
root.innerHTML = '';
root.appendChild(frame);
}
}
})();
//
